// Exercise collection decoding, response contracts, and failure preservation with an in-memory repository.
// Generated by Codex and not thoroughly checked for correctness.
func TestCollectionHandlers(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, tc := range []struct {
		suffix, body string
		status       int
	}{
		{"/move", `{"problem_ids":["A"],"before_problem_id":"B"}`, 200},
		{"/move", `{"problem_ids":["A"],"after_problem_id":"B"}`, 200},
		{"/move", `{"problem_ids":["A"],"before_problem_id":"missing"}`, 409},
		{"/move", `{"problem_ids":["A"],"before_problem_id":"A"}`, 400},
		{"/move", `{"problem_ids":["A"],"unknown":true}`, 400},
		{"", `{"items":[{"problem_id":"C","notes":"hi"}]}`, 200},
		{"", `{"items":[{"problem_id":"A"}]}`, 200},
		{"", `{"items":[{"problem_id":"C"},{"problem_id":"A"}]}`, 200},
		{"", `{"items":[{"problem_id":"C"},{"problem_id":"C"}]}`, 200},
		{"", `{"items":[{"problem_id":"judge:series:problem"}]}`, 200},
		{"", `{"items":[{"problem_id":"C"}],"before_problem_id":"missing"}`, 404},
		{"", `{"items":[{"problem_id":"C"}],"before_problem_id":""}`, 404},
		{"/remove", `{"problem_ids":["missing:opaque/key"]}`, 200},
		{"", `{"items":[{"problem_id":"C"}],"before_problem_id":3}`, 400},
		{"", `{"items":[{"problem_id":"C"}],"after_problem_id":"B"}`, 400},
		{"", `{"items":[{"problem_id":"C","position":1}]}`, 400},
		{"", `{"items":[{"problem_id":"C","status":"bad"}]}`, 400},
		{"", `{"items":[{"problem_id":"C","notes":"\u0000"}]}`, 400},
		{"", `{"items":[]}`, 400},
		{"", `{"items":null}`, 400},
		{"", `{"items":[{"problem_id":"A"},{"problem_id":" "}]}`, 400},
		{"", `{"items":[{"problem_id":"bad\u0000"}]}`, 400},
		{"", `{"items":[{"problem_id":"A"},{"problem_id":"judge:series/problem"}]}`, 400},
		{"", `{"items":[{"problem_id":"judge:series\u002fproblem"}]}`, 400},
		{"", fmt.Sprintf(`{"items":[{"problem_id":%q}]}`, strings.Repeat("界", 101)), 400},
		{"/remove", `{"problem_ids":["A"]}`, 200},
		{"/remove", `{"problem_ids":["A","B","missing"]}`, 200},
		{"/remove", `{"problem_ids":["A","A"]}`, 400},
		{"/remove", `{"problem_ids":["A"," A "]}`, 400},
		{"/remove", `{"problem_ids":["A"," "]}`, 400},
		{"/remove", `{"problem_ids":[]}`, 400},
		{"/remove", `{"problem_ids":5}`, 400},
		{"/move", `{"problem_ids":5}`, 400},
		{"/move", `{"problem_ids":["A","A"]}`, 400},
		{"/move", `{"moves":[{"problem_id":"A"}]}`, 400},
		{"", `{"items":5}`, 400},
		{"", `{"items":[{"problem_id":"C","notes":"` + string([]byte{0xff}) + `"}]}`, 400},
		{"/move", `{`, 400},
		{"", `{} {}`, 400},
		{"", `{"items":[{"problem_id":"C"}]} []`, 400},
	} {
		t.Run(tc.suffix+tc.body, func(t *testing.T) {
			repository := newMockRepository()
			repository.expectedContext = t.Context()
			for index, id := range []string{"A", "B"} {
				item := newListItemFixture()
				item.ProblemId = id
				item.Position = int64(index+1) * configs.ListPositionGap
				repository.storeItem(item)
			}
			before := map[string]items.ListItem{}
			for id, item := range repository.items[testListID] {
				before[id] = item
			}
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, fmt.Sprintf("%s/%d/items%s", testListsPath, testListID, tc.suffix), tc.body)
			assertResponseStatus(t, response, tc.status)
			if tc.status == 400 && len(repository.calls) != 0 {
				t.Fatal("invalid request reached the repository")
			}
			if tc.status >= 400 && !reflect.DeepEqual(before, repository.items[testListID]) {
				t.Fatal("failed request changed records")
			}
			if tc.status == 200 {
				var result items.CollectionResult
				if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
					t.Fatal(err)
				}
				wantPositions := 1
				if tc.suffix == "" {
					wantPositions = len(result.Added)
				}
				if tc.suffix == "/remove" {
					wantPositions = 0
				}
				if result.Order == nil || len(result.Order) != wantPositions {
					t.Fatalf("response included unrelated positions: %+v", result.Order)
				}
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestCollectionHandlersRejectOversizedBatches(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, tc := range []struct {
		name, suffix, property, entryFormat string
	}{
		{"addition", "", "items", `{"problem_id":"A%d"}`},
		{"removal", "/remove", "problem_ids", `"A%d"`},
		{"move", "/move", "problem_ids", `"A%d"`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			repository := newMockRepository()
			entries := make([]string, limits.ItemsPerList+1)
			for i := range entries {
				entries[i] = fmt.Sprintf(tc.entryFormat, i)
			}
			body := fmt.Sprintf(`{%q:[%s]}`, tc.property, strings.Join(entries, ","))
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, itemCollectionPath(testListID)+tc.suffix, body)
			assertResponseStatus(t, response, http.StatusBadRequest)
			if len(repository.calls) != 0 {
				t.Fatal("oversized request reached the repository")
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestBulkAddEnforcesLimitDuringDecoding(t *testing.T) {
	gin.SetMode(gin.TestMode)
	entries := make([]string, limits.ItemsPerList)
	for i := range entries {
		entries[i] = fmt.Sprintf(`{"problem_id":"A%d"}`, i)
	}
	atLimit := strings.Join(entries, ",")
	for _, tc := range []struct {
		name, itemsJSON, message string
	}{
		{name: "accepts exact limit", itemsJSON: atLimit},
		{name: "checks limit before decoding extra item", itemsJSON: atLimit + ",false", message: items.ErrInvalidOperation.Error()},
		{name: "rejects invalid item within limit", itemsJSON: "false", message: testInvalidFormatMessage},
	} {
		t.Run(tc.name, func(t *testing.T) {
			repository := newMockRepository()
			repository.expectedContext = t.Context()
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, itemCollectionPath(testListID), `{"items":[`+tc.itemsJSON+`]}`)
			if tc.message != "" {
				assertResponseStatus(t, response, http.StatusBadRequest)
				assertJSONBody(t, response, errorBody(tc.message))
				if len(repository.calls) != 0 {
					t.Fatal("invalid batch reached the repository")
				}
				return
			}
			assertResponseStatus(t, response, http.StatusOK)
			if len(repository.items[testListID]) != limits.ItemsPerList {
				t.Fatal("valid batch did not reach the repository intact")
			}
		})
	}
}

