// Verify the handler forwards one anchor and exposes the repository duplicate result.
// Generated by Codex and not thoroughly checked for correctness.
func TestAddBatchBeforeOneAnchor(t *testing.T) {
	gin.SetMode(gin.TestMode)
	repository := newMockRepository()
	repository.expectedContext = t.Context()
	for index, id := range []string{"A", "B", "D"} {
		item := newListItemFixture()
		item.ProblemId = id
		item.Position = int64(index+1) * configs.ListPositionGap
		repository.storeItem(item)
	}
	original := repository.items[testListID]["A"]
	response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, itemCollectionPath(testListID), `{"before_problem_id":"B","items":[{"problem_id":"C"},{"problem_id":"A","notes":"Ignored"},{"problem_id":"E"}]}`)
	assertResponseStatus(t, response, http.StatusOK)
	var result items.CollectionResult
	if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
		t.Fatal(err)
	}
	want := []string{"C", "E"}
	if len(result.Order) != len(want) || len(result.Added) != 2 || !reflect.DeepEqual(result.Duplicates, []string{"A"}) {
		t.Fatal(result)
	}
	for index, item := range result.Order {
		if item.ProblemID != want[index] {
			t.Fatal(result.Order)
		}
	}
	if repository.addBefore == nil || *repository.addBefore != "B" || repository.contextMismatch {
		t.Fatalf("anchor=%v context mismatch=%v", repository.addBefore, repository.contextMismatch)
	}
	if !reflect.DeepEqual(original, repository.items[testListID]["A"]) {
		t.Fatal("existing item changed")
	}
}

